import type { Item } from "./claim-office.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  insuredItems: Item[];
}

export interface ClaimResult {
  payout: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

export function openPolicy(insuredItems: Item[]): Policy {
  return { insuredItems };
}

function reimbursement(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages
    .map(reimbursement)
    .reduce((sum, amount) => sum + amount, 0);
  return { payout };
}
