import { describe, expect, it } from "vitest";
import { claim, openPolicy } from "./claim.js";

describe("MHPCO claim processing", () => {
  it("claims a regular steel sword enchantment 3 with damage 500 G -- payout 400 G (full reimbursement minus the 100 G deductible)", () => {
    const policy = openPolicy([
      { type: "sword", material: "steel", enchantment: 3 },
    ]);
    expect(
      claim(policy, {
        cause: "fire",
        damages: [{ itemType: "sword", amount: 500 }],
      }).payout,
    ).toBe(400);
  });
});
=== claim-office.ts ===
export interface Customer {
  yearsWithMHPCO: number;
}

// An item as the MHPCO receives it, mirroring the binding input schema. Every
// field the schema declares is declared here; quote reads only the traits its
// surcharges depend on, so material is carried but unread until a claim
// assesses the dragon-material clause.
export interface Item {
  type: string;
  cursed?: boolean;
  enchantment?: number;
  material?: string;
}

const PROCESSING_FEE = 5;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function alikeComponentGroupSizes(components: Item[]): number[] {
  const sizePerType = new Map<string, number>();
  for (const component of components) {
    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
  }
  return [...sizePerType.values()];
}

// An item's own price per the MHPCO price list. A component is listed at its
// individual price here; the block discount is a property of a group of alike
// components, not of any single component.
function itemBasePremium(item: Item): number {
  return isComponent(item)
    ? COMPONENT_BASE_PREMIUM
    : MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function alikeComponentGroupBasePremium(groupSize: number): number {
  return groupSize === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : groupSize * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremium(components: Item[]): number {
  return alikeComponentGroupSizes(components)
    .map(alikeComponentGroupBasePremium)
    .reduce((sum, premium) => sum + premium, 0);
}

function mainItemsBasePremium(mainItems: Item[]): number {
  return mainItems
    .map(itemBasePremium)
    .reduce((sum, premium) => sum + premium, 0);
}

function policyBasePremium(items: Item[]): number {
  return (
    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
    componentsBasePremium(items.filter(isComponent))
  );
}

interface ItemRisk {
  applies: (item: Item) => boolean;
  surchargeRate: number;
}

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const ITEM_RISKS: ItemRisk[] = [
  { applies: isCursed, surchargeRate: CURSE_SURCHARGE_RATE },
  { applies: isHighlyEnchanted, surchargeRate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
];

function itemRiskSurcharge(item: Item): number {
  return ITEM_RISKS.filter((risk) => risk.applies(item))
    .map((risk) => itemBasePremium(item) * risk.surchargeRate)
    .reduce((sum, surcharge) => sum + surcharge, 0);
}

function itemRiskSurcharges(items: Item[]): number {
  return items
    .map(itemRiskSurcharge)
    .reduce((sum, surcharge) => sum + surcharge, 0);
}

// Every item in a quote is insured for the first time, so the initial assessment
// surcharge applies to every quote -- it does not depend on the customer's history.
function initialAssessmentOnEveryQuote(basePremium: number): number {
  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

interface CustomerStanding {
  yearsWithMHPCO: number;
  previousContracts: number;
}

interface CustomerStandingDiscount {
  earnedBy: (standing: CustomerStanding) => boolean;
  discountRate: number;
}

const isLongStanding = (standing: CustomerStanding): boolean =>
  standing.yearsWithMHPCO >= LOYALTY_YEARS;

const isFollowUpContract = (standing: CustomerStanding): boolean =>
  standing.previousContracts > 0;

const CUSTOMER_STANDING_DISCOUNTS: CustomerStandingDiscount[] = [
  { earnedBy: isLongStanding, discountRate: LOYALTY_DISCOUNT_RATE },
  { earnedBy: isFollowUpContract, discountRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
];

function customerStandingDiscounts(
  standing: CustomerStanding,
  basePremium: number,
): number {
  return CUSTOMER_STANDING_DISCOUNTS.filter((discount) =>
    discount.earnedBy(standing),
  )
    .map((discount) => basePremium * discount.discountRate)
    .reduce((sum, amount) => sum + amount, 0);
}

function policyWideModifiers(
  standing: CustomerStanding,
  basePremium: number,
): number {
  return (
    initialAssessmentOnEveryQuote(basePremium) -
    customerStandingDiscounts(standing, basePremium)
  );
}

function premiumRoundedInMhpcosFavor(premium: number): number {
  return Math.ceil(premium);
}

export function quote(
  customer: Customer,
  items: Item[],
  previousContracts: number,
): number {
  const basePremium = policyBasePremium(items);
  const standing = { ...customer, previousContracts };
  const premium =
    basePremium +
    itemRiskSurcharges(items) +
    policyWideModifiers(standing, basePremium) +
    PROCESSING_FEE;
  return premiumRoundedInMhpcosFavor(premium);
}
